def main():
    loc = os.path.join(ROOT, "nimcale", "i18n", "locales")
    for i, code in enumerate(LANGS):
        path = os.path.join(loc, code + ".json")
        d = json.load(open(path, encoding="utf-8"))
        for k, vals in T.items():
            assert len(vals) == len(LANGS), k
            d[k] = vals[i].replace("\\\\n", "\\n")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(dict(sorted(d.items())), f, ensure_ascii=False, indent=2)
            f.write("\n")
    print("merged %d keys into %d locales" % (len(T), len(LANGS)))


if __name__ == "__main__":
    main()
